<script setup lang="ts">
import { ArrowLeft,ArrowRight,CheckCircle2,AlertCircle,FileText,ShieldCheck } from 'lucide-vue-next'
import type { Procedure,Application,CaseDocument } from '~/types/models'
const route=useRoute()
const {data:p,error:procedureError}=await useFetch<Procedure>(`/api/procedures/${route.params.slug}`, {key:`citizen-procedure:${String(route.params.slug)}`})
const {data:profile}=await useFetch<{display_name:string;phone:string;email:string;address:string}>('/api/profile', {key:'citizen-profile'})
const step=ref(Number(route.query.step)||1)
const draftId=ref(String(route.query.draft||''))
const busy=ref(false);const errorText=ref('');const confirmed=ref(false)
const form=reactive({applicantName:'',phone:'',description:'',childName:'',birthDate:'',gender:'Nam',birthPlace:'',subject:''})
const uploaded=ref<CaseDocument[]>([])
watch(profile,(v)=>{if(v&&!form.applicantName){form.applicantName=v.display_name;form.phone=v.phone}},{immediate:true})
const missing=computed(()=>p.value?.documents?.filter(d=>d.is_required&&!uploaded.value.some(u=>u.document_code===d.document_code))||[])
const canNext=computed(()=>form.applicantName.trim().length>=2&&(p.value?.id!=='khai-sinh'||(form.childName.trim()&&form.birthDate)))
onMounted(async()=>{if(draftId.value){try{const a=await $fetch<Application>(`/api/applications/${draftId.value}`);if(a.status!=='draft')return; uploaded.value=a.documents||[];form.applicantName=a.applicant_name;form.phone=a.applicant_phone||'';form.description=a.description;Object.assign(form,a.form_data||{})}catch{/* draft was removed or belongs to someone else */}}})
async function goStep(next:number){step.value=next;await navigateTo({path:route.path,query:{step:String(next),...(draftId.value?{draft:draftId.value}:{})}},{replace:true})}
async function saveDraft(){
 if(!p.value||!canNext.value)return
 busy.value=true;errorText.value=''
 try {
  const payload={procedureId:p.value.id,applicantName:form.applicantName,phone:form.phone,description:form.description,formData:{childName:form.childName,birthDate:form.birthDate,gender:form.gender,birthPlace:form.birthPlace,subject:form.subject}}
  if(!draftId.value){const response=await $fetch<{id:string}>('/api/applications',{method:'POST',body:payload});draftId.value=response.id}
  else await $fetch(`/api/applications/${draftId.value}`,{method:'PATCH',body:payload})
  await goStep(2)
 } catch(e){errorText.value=readableError(e)}finally{busy.value=false}
}
async function submit(){if(!draftId.value||missing.value.length||!confirmed.value)return
 busy.value=true;errorText.value=''
 try {await $fetch(`/api/applications/${draftId.value}/submit`,{method:'POST',body:{confirmed:true}});await navigateTo(`/nop-thanh-cong/${draftId.value}`)}catch(e){errorText.value=readableError(e)}finally{busy.value=false}
}
</script>
<template><div class="space-y-4"><NuxtLink :to="`/thu-tuc/${route.params.slug}`" class="inline-flex items-center gap-1 text-xs font-semibold text-brand-700"><ArrowLeft :size="14"/> Chi tiết thủ tục</NuxtLink><div v-if="procedureError" class="panel p-6 text-rose-600">Không tìm thấy thủ tục.</div>
 <template v-else-if="p"><div class="panel p-4"><div class="mb-3 flex flex-wrap items-center justify-between gap-3"><div><p class="text-xs font-bold text-brand-600">THỦ TỤC TRỰC TUYẾN</p><h2 class="text-xl font-black">{{p.title}}</h2></div><span v-if="draftId" class="rounded-lg bg-blue-50 px-3 py-2 text-xs font-bold text-blue-700">Bản nháp: {{draftId}}</span></div><div class="grid grid-cols-3 gap-2"><div v-for="(title,index) in ['Điền biểu mẫu','Tải giấy tờ','Xác nhận & nộp']" :key="title" :class="['rounded-lg px-2 py-3 text-center text-xs font-bold sm:text-sm',step===index+1?'bg-brand-600 text-white':step>index+1?'bg-green-100 text-green-800':'bg-slate-100 text-slate-500']">{{index+1}}. {{title}}</div></div></div>
 <form v-if="step===1" class="panel space-y-5 p-5" @submit.prevent="saveDraft"><h3 class="section-label">Thông tin người nộp hồ sơ</h3><div class="grid gap-4 sm:grid-cols-2"><div><label class="field-label">Họ và tên <span class="text-rose-500">*</span></label><input v-model="form.applicantName" class="field" required minlength="2" maxlength="100" autocomplete="name"/></div><div><label class="field-label">Số điện thoại</label><input v-model="form.phone" class="field" maxlength="20" inputmode="tel"/></div><div class="sm:col-span-2"><label class="field-label">Ghi chú</label><textarea v-model="form.description" class="field" rows="2" maxlength="500" placeholder="Ghi chú thêm (nếu có)"/></div></div>
 <template v-if="p.id==='khai-sinh'"><h3 class="section-label !mb-0 border-t border-slate-100 pt-4">Thông tin trẻ đăng ký khai sinh</h3><div class="grid gap-4 sm:grid-cols-2"><div><label class="field-label">Họ và tên trẻ <span class="text-rose-500">*</span></label><input v-model="form.childName" class="field" required maxlength="100"/></div><div><label class="field-label">Ngày sinh <span class="text-rose-500">*</span></label><input v-model="form.birthDate" class="field" type="date" required/></div><div><label class="field-label">Giới tính</label><select v-model="form.gender" class="field"><option>Nam</option><option>Nữ</option><option>Khác</option></select></div><div><label class="field-label">Nơi sinh</label><input v-model="form.birthPlace" class="field" placeholder="Nơi sinh (mô phỏng)" maxlength="200"/></div></div></template>
 <template v-else><h3 class="section-label !mb-0 border-t pt-4">Thông tin đề nghị</h3><div><label class="field-label">Nội dung / đối tượng thủ tục</label><input v-model="form.subject" class="field" maxlength="200" placeholder="Nhập nội dung đề nghị (mô phỏng)"/></div></template>
 <div class="flex flex-col items-stretch gap-3 border-t pt-4 sm:flex-row sm:items-center sm:justify-between"><span class="text-xs text-muted">Các ô * là bắt buộc</span><button type="submit" class="btn-primary w-full sm:w-auto" :disabled="!canNext||busy">{{busy?'Đang lưu...':'Lưu nháp và tiếp tục'}} <ArrowRight :size="16"/></button></div></form>
 <section v-else-if="step===2" class="panel space-y-4 p-5"><div><h3 class="section-label"><FileText class="text-brand-600" :size="21"/>Thành phần giấy tờ (Poka-yoke)</h3><p class="text-sm text-muted">Tải đủ giấy tờ có dấu * để được phép nộp hồ sơ.</p></div><DocUploader :application-id="draftId" :requirements="p.documents||[]" :uploaded="uploaded" @uploaded="uploaded.push($event)"/><div :class="['rounded-lg p-3 text-sm font-semibold',missing.length?'bg-amber-50 text-amber-800':'bg-green-50 text-green-800']"><AlertCircle v-if="missing.length" :size="16" class="mr-1 inline"/><CheckCircle2 v-else :size="16" class="mr-1 inline"/>{{missing.length?`Còn thiếu ${missing.length} giấy tờ bắt buộc: ${missing.map(d=>d.document_name).join(', ')}`:'Đã có đủ các loại giấy tờ bắt buộc.'}}</div><div class="flex flex-col gap-2 border-t pt-4 sm:flex-row sm:justify-between"><button class="btn-outline w-full sm:w-auto" @click="goStep(1)"><ArrowLeft :size="15"/> Quay lại</button><button class="btn-primary w-full sm:w-auto" :disabled="!!missing.length" @click="goStep(3)">Tiếp tục rà soát <ArrowRight :size="15"/></button></div></section>
 <section v-else-if="step===3" class="panel space-y-4 p-5"><h3 class="section-label"><ShieldCheck class="text-brand-600" :size="21"/>Rà soát và xác nhận</h3><div class="grid gap-3 sm:grid-cols-2"><p class="rounded-lg bg-brand-50 p-3 text-sm"><b class="block">Thủ tục</b>{{p.title}}</p><p class="rounded-lg bg-brand-50 p-3 text-sm"><b class="block">Người nộp</b>{{form.applicantName}}</p><p class="rounded-lg bg-brand-50 p-3 text-sm"><b class="block">Mã bản nháp</b>{{draftId}}</p><p class="rounded-lg bg-brand-50 p-3 text-sm"><b class="block">Giấy tờ</b>{{uploaded.length}} tệp đã tải lên</p></div><div class="rounded-lg border border-green-200 bg-green-50 p-3 text-sm text-green-900">Đã đủ {{p.documents?.filter(d=>d.is_required).length||0}} loại giấy tờ bắt buộc của bản mô phỏng.</div><label class="flex cursor-pointer items-start gap-3 rounded-lg border p-3 text-sm"><input v-model="confirmed" type="checkbox" class="mt-1 h-4 w-4 accent-brand-600"/><span>Tôi xác nhận thông tin đã kê khai và giấy tờ đã đính kèm là chính xác; hiểu đây là hệ thống thử nghiệm với dữ liệu giả.</span></label><div class="flex flex-col gap-2 border-t pt-4 sm:flex-row sm:justify-between"><button class="btn-outline w-full sm:w-auto" @click="goStep(2)"><ArrowLeft :size="15"/> Quay lại</button><button class="btn-primary w-full sm:w-auto" :disabled="!confirmed||!!missing.length||busy" @click="submit">{{busy?'Đang gửi...':'Xác nhận & nộp hồ sơ'}} <CheckCircle2 :size="16"/></button></div></section>
 <p v-if="errorText" role="alert" class="rounded-lg border border-rose-200 bg-rose-50 p-3 text-sm text-rose-700">{{errorText}}</p><p class="text-xs text-muted">Thời hạn, thành phần và nghiệp vụ ở đây là minh họa; chưa kết nối Flowable, OCR hoặc chữ ký số thật.</p></template></div></template>
